CREATE TABLE users (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, name VARCHAR(160) NOT NULL, email VARCHAR(190) NOT NULL UNIQUE, password_hash VARCHAR(255), email_verified_at DATETIME NULL, remember_token_hash VARCHAR(100), ai_credits INT DEFAULT 0, ats_scans INT DEFAULT 0, status VARCHAR(40) DEFAULT 'active', created_at DATETIME NOT NULL, updated_at DATETIME NULL, INDEX idx_users_created(created_at)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE user_profiles (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, user_id BIGINT UNSIGNED NOT NULL UNIQUE, phone VARCHAR(60), location VARCHAR(190), website VARCHAR(190), linkedin VARCHAR(190), github VARCHAR(190), portfolio VARCHAR(190), photo_path VARCHAR(255), preferences JSON NULL, FOREIGN KEY (user_id) REFERENCES users(id) ON DELETE CASCADE) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE oauth_accounts (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, user_id BIGINT UNSIGNED NOT NULL, provider VARCHAR(40) NOT NULL, provider_user_id VARCHAR(190) NOT NULL, created_at DATETIME NOT NULL, UNIQUE KEY uniq_oauth(provider, provider_user_id), FOREIGN KEY (user_id) REFERENCES users(id) ON DELETE CASCADE) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE admin_users (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, name VARCHAR(160) NOT NULL, email VARCHAR(190) NOT NULL UNIQUE, password_hash VARCHAR(255) NOT NULL, role ENUM('super_admin','admin','support','content_manager') NOT NULL DEFAULT 'admin', created_at DATETIME NOT NULL) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE resumes (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, user_id BIGINT UNSIGNED NOT NULL, name VARCHAR(190) NOT NULL, template_key VARCHAR(80) DEFAULT 'modern', public_token CHAR(48) NULL UNIQUE, public_enabled TINYINT(1) DEFAULT 0, ats_score INT DEFAULT 0, completion_percent INT DEFAULT 0, status ENUM('active','archived','deleted') DEFAULT 'active', created_at DATETIME NOT NULL, updated_at DATETIME NULL, FOREIGN KEY (user_id) REFERENCES users(id) ON DELETE CASCADE, INDEX idx_resumes_user_status(user_id,status)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE resume_sections (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, resume_id BIGINT UNSIGNED NOT NULL, section_key VARCHAR(80) NOT NULL, title VARCHAR(160) NOT NULL, sort_order INT DEFAULT 0, is_visible TINYINT(1) DEFAULT 1, content JSON NULL, FOREIGN KEY (resume_id) REFERENCES resumes(id) ON DELETE CASCADE, INDEX idx_sections_order(resume_id,sort_order)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE resume_experiences (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, resume_id BIGINT UNSIGNED NOT NULL, job_title VARCHAR(190), company VARCHAR(190), location VARCHAR(190), employment_type VARCHAR(80), start_date DATE NULL, end_date DATE NULL, is_current TINYINT(1) DEFAULT 0, responsibilities TEXT, achievements TEXT, sort_order INT DEFAULT 0, FOREIGN KEY (resume_id) REFERENCES resumes(id) ON DELETE CASCADE) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE resume_education (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, resume_id BIGINT UNSIGNED NOT NULL, institution VARCHAR(190), degree VARCHAR(190), field_of_study VARCHAR(190), start_date DATE NULL, end_date DATE NULL, grade VARCHAR(80), description TEXT, sort_order INT DEFAULT 0, FOREIGN KEY (resume_id) REFERENCES resumes(id) ON DELETE CASCADE) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE resume_skills (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, resume_id BIGINT UNSIGNED NOT NULL, category VARCHAR(80), skill VARCHAR(160) NOT NULL, proficiency VARCHAR(60), sort_order INT DEFAULT 0, FOREIGN KEY (resume_id) REFERENCES resumes(id) ON DELETE CASCADE) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE resume_projects (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, resume_id BIGINT UNSIGNED NOT NULL, project_name VARCHAR(190), role VARCHAR(160), technologies VARCHAR(255), url VARCHAR(255), description TEXT, achievements TEXT, sort_order INT DEFAULT 0, FOREIGN KEY (resume_id) REFERENCES resumes(id) ON DELETE CASCADE) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE resume_versions (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, resume_id BIGINT UNSIGNED NOT NULL, snapshot JSON NOT NULL, source VARCHAR(80) NOT NULL, created_at DATETIME NOT NULL, FOREIGN KEY (resume_id) REFERENCES resumes(id) ON DELETE CASCADE) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE resume_templates (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, name VARCHAR(120) NOT NULL, template_key VARCHAR(80) NOT NULL UNIQUE, settings JSON NOT NULL, active TINYINT(1) DEFAULT 1) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE ai_providers (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, name VARCHAR(120) NOT NULL, provider_type ENUM('openai','anthropic','gemini','custom') NOT NULL, base_url VARCHAR(255) NOT NULL, api_key_encrypted TEXT NOT NULL, model VARCHAR(160) NOT NULL, temperature DECIMAL(3,2) DEFAULT 0.40, max_tokens INT DEFAULT 900, active TINYINT(1) DEFAULT 0, priority INT DEFAULT 100, estimated_input_cost DECIMAL(12,6) DEFAULT 0, estimated_output_cost DECIMAL(12,6) DEFAULT 0, created_at DATETIME NOT NULL) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE ai_prompts (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, prompt_key VARCHAR(120) NOT NULL UNIQUE, name VARCHAR(160) NOT NULL, system_prompt TEXT NOT NULL, user_prompt TEXT NOT NULL, temperature DECIMAL(3,2) NULL, max_tokens INT NULL, active TINYINT(1) DEFAULT 1) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE ai_logs (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, user_id BIGINT UNSIGNED NULL, provider_id BIGINT UNSIGNED NULL, model VARCHAR(160), request_type VARCHAR(120) NOT NULL, success TINYINT(1) NOT NULL, error_message TEXT NULL, input_tokens INT NULL, output_tokens INT NULL, response_time_ms INT NULL, created_at DATETIME NOT NULL, INDEX idx_ai_logs_created(created_at), FOREIGN KEY (user_id) REFERENCES users(id) ON DELETE SET NULL, FOREIGN KEY (provider_id) REFERENCES ai_providers(id) ON DELETE SET NULL) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE ai_credit_transactions (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, user_id BIGINT UNSIGNED NOT NULL, action VARCHAR(120) NOT NULL, credits INT NOT NULL, idempotency_key VARCHAR(120) NOT NULL UNIQUE, provider_id BIGINT UNSIGNED NULL, model VARCHAR(160), created_at DATETIME NOT NULL, FOREIGN KEY (user_id) REFERENCES users(id) ON DELETE CASCADE) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE job_descriptions (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, user_id BIGINT UNSIGNED NOT NULL, title VARCHAR(190), raw_text MEDIUMTEXT NOT NULL, analysis JSON NULL, created_at DATETIME NOT NULL, FOREIGN KEY (user_id) REFERENCES users(id) ON DELETE CASCADE) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE ats_scans (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, user_id BIGINT UNSIGNED NOT NULL, resume_id BIGINT UNSIGNED NULL, score INT NOT NULL, result JSON NOT NULL, created_at DATETIME NOT NULL, FOREIGN KEY (user_id) REFERENCES users(id), FOREIGN KEY (resume_id) REFERENCES resumes(id) ON DELETE SET NULL) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE plans (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, name VARCHAR(120) NOT NULL, price DECIMAL(12,2) DEFAULT 0, currency CHAR(3) DEFAULT 'USD', limits JSON NOT NULL, active TINYINT(1) DEFAULT 1) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE subscriptions (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, user_id BIGINT UNSIGNED NOT NULL, plan_id BIGINT UNSIGNED NOT NULL, status VARCHAR(40) NOT NULL, starts_at DATETIME NOT NULL, ends_at DATETIME NULL, FOREIGN KEY (user_id) REFERENCES users(id), FOREIGN KEY (plan_id) REFERENCES plans(id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE payments (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, user_id BIGINT UNSIGNED NOT NULL, provider VARCHAR(60) NOT NULL, amount DECIMAL(12,2) NOT NULL, currency CHAR(3) NOT NULL, status VARCHAR(60) NOT NULL, provider_reference VARCHAR(190), verified_at DATETIME NULL, created_at DATETIME NOT NULL, FOREIGN KEY (user_id) REFERENCES users(id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE email_settings (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, host VARCHAR(190), port INT, username VARCHAR(190), password_encrypted TEXT, encryption VARCHAR(20), from_email VARCHAR(190), from_name VARCHAR(190), active TINYINT(1) DEFAULT 1) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE email_templates (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, template_key VARCHAR(120) NOT NULL UNIQUE, subject VARCHAR(190) NOT NULL, body_html MEDIUMTEXT NOT NULL, active TINYINT(1) DEFAULT 1) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE notifications (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, user_id BIGINT UNSIGNED NOT NULL, message VARCHAR(255) NOT NULL, read_at DATETIME NULL, created_at DATETIME NOT NULL, FOREIGN KEY (user_id) REFERENCES users(id) ON DELETE CASCADE) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE password_resets (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, user_id BIGINT UNSIGNED NOT NULL, token_hash CHAR(64) NOT NULL, expires_at DATETIME NOT NULL, used_at DATETIME NULL, created_at DATETIME NOT NULL, FOREIGN KEY (user_id) REFERENCES users(id) ON DELETE CASCADE) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE email_verifications (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, user_id BIGINT UNSIGNED NOT NULL, token_hash CHAR(64) NOT NULL, expires_at DATETIME NOT NULL, used_at DATETIME NULL, created_at DATETIME NOT NULL, FOREIGN KEY (user_id) REFERENCES users(id) ON DELETE CASCADE) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE admin_activity_logs (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, admin_user_id BIGINT UNSIGNED NULL, action VARCHAR(190) NOT NULL, meta JSON NULL, created_at DATETIME NOT NULL, FOREIGN KEY (admin_user_id) REFERENCES admin_users(id) ON DELETE SET NULL) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE system_settings (setting_key VARCHAR(120) PRIMARY KEY, setting_value JSON NOT NULL, updated_at DATETIME NULL) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
